// Shader.metal
#include <metal_stdlib>
using namespace metal;

[[ stitchable ]] half4 hellfire(float2 position, float time, float2 size, float intensity) {
    float2 uv = position / max(size, float2(1.0));
    float wave = sin(uv.x * 18.0 + time * 2.2) * 0.08;
    float heat = smoothstep(1.05, 0.05, uv.y + wave);
    half3 cold = half3(0.05, 0.0, 0.0);
    half3 hot = half3(1.0, 0.28, 0.02);
    return half4(mix(cold, hot, half(heat * intensity)), 1.0);
}

