// Shader.metal
[[ stitchable ]] float2 floorWave(float2 position, float time, float amplitude) {
    float perspective = clamp(position.y / 700.0, 0.0, 1.0);
    float offset = sin(position.x * 0.035 + time * 2.0) * amplitude * perspective;
    return position + float2(0.0, offset);
}

